-- Packed rects are offset so every byte lands in printable ASCII; see
-- tools/fruitart.py, which is the only thing that writes them.
local ART_OFFSET = 40

-- Chrome. These exact values are a contract with tests/fruits/frame.lua, which
-- recovers the board from the paint calls: on the image path a cell's fruit is
-- the drawImage in it, and on the rect fallback it is whatever is filled inside
-- the cell that is not one of these.
local PAGE_BG  = {  14,  16,  22 }
local HUD_BG   = {  26,  30,  40 }
local HUD_RULE = {  52,  58,  74 }
local BOARD_BG = {  34,  39,  52 }
local CELL_A   = {  46,  52,  68 }
local CELL_B   = {  39,  45,  60 }
local PANEL_BG = {  22,  26,  34 }

-- Cursor and hint are drawn as OUTLINES, never fills. That is not decoration:
-- it is what lets the frame reader take every fill inside a cell as fruit and
-- never have to subtract chrome that moves around. Nothing else paints inside
-- the board, and tests/fruits/ui.lua fails if anything starts.
local CURSOR   = { 250, 238, 120 }
local SELECT   = { 120, 224, 255 }
local HINT     = { 120, 250, 160 }

local GOLD     = { 250, 190,  70 }
local TEXT     = { 226, 231, 242 }
local DIM      = { 138, 146, 166 }
local RED      = { 232,  78,  68 }

local ui = { w = 318, h = 212, bx = 0, by = HUD_H, cell = 20, sprite = 16,
             side = 160, panelW = 0, pad = 2 }

local board                     -- the Fruit instance; built by newRound
local cur = { x = 4, y = 4 }    -- the cursor
local sel = nil                 -- { x, y } while a fruit is picked up

-- math.randomseed does nothing on the handheld, so the game owns its
-- generator and this is what seeds it: every tick, key and click folded in.
-- Two launches differ by only a few idle ticks, which is exactly the case
-- Fruit.newRandom is built to scramble apart.
local entropy = 1

local function stir(v)
  entropy = Fruit.mix(entropy, v)
end

local function col(gc, c)
  gc:setColorRGB(c[1], c[2], c[3])
end

local function newRound()
  board = Fruit.new({
    rand = Fruit.newRandom(entropy),
    best = board and board.best or 0,
  })
  cur.x, cur.y = 4, 4
  sel = nil
end

-- The sprites, as TI.Image objects, or nil if this runtime will not make them.
--
-- gc:drawImage draws a whole fruit in one call where the rects below take
-- sixty-odd, which is the difference between 64 calls and 4123 for a board
-- that repaints on every tick of a cascade. It is worth the care it needs.
--
-- The care: image.new's string form is documented only for apilevel < 2.3
-- (from 2.3 it wants a TI.ResourceHandle built by TI's own SDK), and it was
-- verified on one CX II with tools/probe/imageprobe2.lua -- one calculator, one
-- OS. So it is built inside a pcall and the whole thing is all-or-nothing: if
-- any sprite fails to build, every fruit falls back to the rects, because half
-- the board in one encoding and half in the other would look like a bug rather
-- than a fallback. The rects are not a lesser picture -- tools/fruitart.py
-- checks the two encodings against the source and against each other, pixel
-- for pixel -- they are only slower.
local sprites = (function()
  if type(image) ~= "table" or type(image.new) ~= "function" then return nil end
  local out = {}
  for i = 1, #ART do
    local built, img = pcall(image.new, ART[i].img)
    if not built or not img then return nil end
    out[i] = img
  end
  return out
end)()

-- ------------------------------------------------------------------ sprites --

-- Draws fruit `kind` with its top-left at (px, py), `size` pixels square.
--
-- At the native size with images available -- which is every cell on the
-- handheld -- this is one call. Everything else goes through the rects: a cell
-- too small for a 16-pixel sprite, a fruit shrinking as it bursts, or a
-- runtime that would not build the images at all.
--
-- The scaled path maps BOTH edges of a rect through the same rounding.
-- Rounding origin and extent separately leaves one-pixel seams of background
-- between rects that should be touching, which at small sizes turns a fruit
-- into a grid of confetti.
local function drawFruit(gc, kind, px, py, size)
  local a = ART[kind]
  if not a then return end

  if sprites and size == ART_SIZE then
    gc:drawImage(sprites[kind], px, py)
    return
  end

  local pal, runs = a.pal, a.runs
  if size == ART_SIZE then
    for c = 1, #runs do
      local str = runs[c]
      if #str > 0 then
        gc:setColorRGB(pal[c * 3 - 2], pal[c * 3 - 1], pal[c * 3])
        for i = 1, #str, 4 do
          local x, y, w, h = byte(str, i, i + 3)
          gc:fillRect(px + x - ART_OFFSET, py + y - ART_OFFSET,
                      w - ART_OFFSET, h - ART_OFFSET)
        end
      end
    end
    return
  end

  for c = 1, #runs do
    local str = runs[c]
    if #str > 0 then
      gc:setColorRGB(pal[c * 3 - 2], pal[c * 3 - 1], pal[c * 3])
      for i = 1, #str, 4 do
        local x, y, w, h = byte(str, i, i + 3)
        x, y = x - ART_OFFSET, y - ART_OFFSET
        local x0 = floor(x * size / ART_SIZE)
        local y0 = floor(y * size / ART_SIZE)
        local x1 = floor((x + w - ART_OFFSET) * size / ART_SIZE)
        local y1 = floor((y + h - ART_OFFSET) * size / ART_SIZE)
        gc:fillRect(px + x0, py + y0, max(1, x1 - x0), max(1, y1 - y0))
      end
    end
  end
end

-- --------------------------------------------------------------- geometry --

local function cellX(gx) return ui.bx + (gx - 1) * ui.cell end
local function cellY(gy) return ui.by + (gy - 1) * ui.cell end

-- Where a sprite sits inside its cell.
local function spriteX(gx) return cellX(gx) + ui.pad end
local function spriteY(gy) return cellY(gy) + ui.pad end

-- The cell under a click, or nil.
local function cellAt(px, py)
  local gx = floor((px - ui.bx) / ui.cell) + 1
  local gy = floor((py - ui.by) / ui.cell) + 1
  if Fruit.inside(gx, gy) then return gx, gy end
  return nil
end

-- Called before the first paint, and again on every resize -- which on a
-- handheld means never, but the computer software resizes freely.
function on.resize(w, h)
  ui.w, ui.h = w, h

  -- The hint strip is the first thing to go when the window is short.
  local hintH = (h - HUD_H >= 128) and 14 or 0
  local avail = h - HUD_H - hintH - 4

  -- Size the board once to find out whether a side panel would still fit
  -- beside it, then size it again with the panel's width taken out.
  local cell = floor(min(w - 8, avail) / N)
  local panelW = 0
  if w - (cell * N + 12) >= MIN_PANEL then
    panelW = min(140, w - (cell * N + 12))
    cell = floor(min(w - 12 - panelW, avail) / N)
  end
  if cell < 5 then cell = 5 end

  -- Only ever an integer multiple of the art, never a fractional blow-up: a
  -- 16-pixel sprite stretched to 21 is a smear, and the extra pixels are
  -- better spent on the gutter between fruit, which is what makes a run of
  -- three read as three things rather than one stripe.
  local k = floor((cell - 4) / ART_SIZE)
  ui.sprite = (k >= 1) and (ART_SIZE * k) or max(3, cell - 2)
  ui.pad = floor((cell - ui.sprite) / 2)

  ui.cell = cell
  ui.side = cell * N
  ui.panelW = panelW
  ui.bx = max(2, floor((w - panelW - ui.side) / 2))
  ui.by = max(HUD_H, HUD_H + floor((h - HUD_H - hintH - ui.side) / 2))

  ui.panelX = ui.bx + ui.side + 6
  ui.panelH = ui.side
  if ui.panelX + panelW > w - 2 then panelW = max(0, w - 2 - ui.panelX) end
  ui.panelW = (panelW >= MIN_PANEL) and panelW or 0

  ui.hintY = ui.by + ui.side + 3
  ui.hint = hintH > 0 and (ui.hintY + 13 <= h)

  platform.window:invalidate()
end

-- --------------------------------------------------------------- lifecycle --

newRound()
timer.start(BASE_TICK)

function on.timer()
  stir(1)
  if board:busy() then
    board:tick()
    platform.window:invalidate()   -- something is moving; keep the frames coming
  end
end

function on.deactivate()
  board:pause()
  platform.window:invalidate()
end

-- ------------------------------------------------------------------- input --

local function confirm()
  local s = board.state
  if s == "ready" then
    board:start()
  elseif s == "over" then
    newRound()
    board:start()
  elseif s == "paused" then
    board:resume()
  elseif s == "playing" and board.phase == "idle" then
    -- enter picks a fruit up, and puts it back down.
    if sel and sel.x == cur.x and sel.y == cur.y then
      sel = nil
    else
      sel = { x = cur.x, y = cur.y }
    end
  end
end

local DELTA = {
  up    = {  0, -1 },
  down  = {  0,  1 },
  left  = { -1,  0 },
  right = {  1,  0 },
}

-- An arrow with a fruit picked up is the swap itself: one keypress, no
-- confirm. Without a selection it just walks the cursor.
local function steer(dir)
  local d = DELTA[dir]
  if not d then return end

  if board.state == "ready" then board:start() end
  if board.state ~= "playing" or board.phase ~= "idle" then return end

  if sel then
    local tx, ty = sel.x + d[1], sel.y + d[2]
    if Fruit.inside(tx, ty) then
      board:swap(sel.x, sel.y, tx, ty)
      cur.x, cur.y = tx, ty
      sel = nil
    end
    return
  end

  local nx, ny = cur.x + d[1], cur.y + d[2]
  if Fruit.inside(nx, ny) then cur.x, cur.y = nx, ny end
end

function on.arrowKey(key)
  stir(2)
  steer(key)
  platform.window:invalidate()
end

function on.enterKey()
  stir(3)
  confirm()
  platform.window:invalidate()
end

function on.escapeKey()
  stir(5)
  if board.state == "playing" then
    board:pause()
  elseif board.state == "paused" then
    board:resume()
  end
  platform.window:invalidate()
end

-- The keypad reads 7 8 9 / 4 5 6 / 1 2 3, so 2/4/6/8 are the arrows, the same
-- way every other game in this repo takes them.
local CHAR_DIRS = {
  w = "up",    ["8"] = "up",
  s = "down",  ["2"] = "down",
  a = "left",  ["4"] = "left",
  d = "right", ["6"] = "right",
}

function on.charIn(ch)
  ch = string.lower(ch or "")
  stir(7)

  local dir = CHAR_DIRS[ch]
  if dir then
    steer(dir)
  elseif ch == " " or ch == "5" then
    confirm()
  elseif ch == "p" then
    if board.state == "playing" then board:pause()
    elseif board.state == "paused" then board:resume() end
  elseif ch == "r" then
    newRound()
    board:start()
  elseif ch == "h" then
    board:showHint()
  end

  platform.window:invalidate()
end

-- Click to pick up, click a neighbour to swap. Clicking anywhere else moves
-- the pick-up rather than refusing, which is what a player expects from a
-- touchpad they cannot aim precisely with.
function on.mouseDown(px, py)
  stir(11)
  local s = board.state

  if s ~= "playing" then
    confirm()
    platform.window:invalidate()
    return
  end

  local gx, gy = cellAt(px, py)
  if gx and board.phase == "idle" then
    cur.x, cur.y = gx, gy
    if sel and Fruit.adjacent(sel.x, sel.y, gx, gy) then
      board:swap(sel.x, sel.y, gx, gy)
      sel = nil
    elseif sel and sel.x == gx and sel.y == gy then
      sel = nil
    else
      sel = { x = gx, y = gy }
    end
  end
  platform.window:invalidate()
end

-- ----------------------------------------------------------------- drawing --

-- Which cells must NOT be drawn sitting on their own square, because they are
-- in flight and will be drawn tweened instead. Rebuilt per frame; 64 booleans
-- is cheaper than any bookkeeping that would avoid it.
local moving = {}

local function markMoving()
  for i = 1, Fruit.CELLS do moving[i] = false end
  local m = board.motion
  for i = 1, #m do
    local e = m[i]
    local x = e.x
    local y = e.toY or e.y
    if Fruit.inside(x, y) then moving[(y - 1) * N + x] = true end
  end
end

local function drawCells(gc)
  col(gc, BOARD_BG)
  gc:fillRect(ui.bx, ui.by, ui.side, ui.side)

  -- A checker, so a row of eight cells reads as eight cells even where three
  -- neighbours are the same fruit.
  for y = 1, N do
    for x = 1, N do
      col(gc, ((x + y) % 2 == 0) and CELL_A or CELL_B)
      gc:fillRect(cellX(x), cellY(y), ui.cell, ui.cell)
    end
  end
end

-- The fruit that are sitting still. During `clear` the matched ones are still
-- on the board -- that is the phase's whole job, to show them going -- so they
-- are drawn shrinking over a pale backing instead of being skipped.
local function drawStatic(gc)
  local bursting = (board.phase == "clear")
  local p = bursting and board:phaseProgress() or 0
  local shrunk = max(2, floor(ui.sprite * (1 - p * 0.75)))
  local marked = board.marked

  for y = 1, N do
    for x = 1, N do
      local i = (y - 1) * N + x
      if not moving[i] then
        local k = board.cells[i]
        if k and k ~= 0 then
          if bursting and marked[i] then
            -- Shrinking, over nothing. An earlier version put a pale rect
            -- behind a bursting fruit to say "this one is going"; at cell size
            -- and near-white it read as a rendering fault rather than a cue,
            -- and the shrink says it on its own.
            local off = floor((ui.cell - shrunk) / 2)
            drawFruit(gc, k, cellX(x) + off, cellY(y) + off, shrunk)
          else
            -- A picked-up fruit rides a little high, so the pick-up reads even
            -- where the cursor ring is sitting on top of it. Never more than
            -- the gutter, or it would climb out of its own cell.
            local lift = (sel and sel.x == x and sel.y == y) and min(2, ui.pad) or 0
            drawFruit(gc, k, spriteX(x), spriteY(y) - lift, ui.sprite)
          end
        end
      end
    end
  end
end

-- Everything in flight, at its interpolated position. Falling fruit come from
-- above the board and are deliberately allowed to overflow upward: on.paint
-- repaints the HUD bar afterwards, which covers the overflow for nothing,
-- rather than paying to clip every rect.
local function drawMoving(gc)
  local m = board.motion
  if #m == 0 then return end

  local p = board:phaseProgress()
  for i = 1, #m do
    local e = m[i]
    local fx = e.fromX or e.x
    local fy = e.fromY
    local tx = e.toX or e.x
    local ty = e.toY
    local px = spriteX(fx) + (spriteX(tx) - spriteX(fx)) * p
    local py = spriteY(fy) + (spriteY(ty) - spriteY(fy)) * p
    drawFruit(gc, e.kind, floor(px + 0.5), floor(py + 0.5), ui.sprite)
  end
end

local function outline(gc, c, x, y, inset)
  col(gc, c)
  gc:drawRect(cellX(x) + inset, cellY(y) + inset,
              ui.cell - 1 - inset * 2, ui.cell - 1 - inset * 2)
end

-- One ring on the cursor's cell, not two stacked.
--
-- Picking a fruit up never moves the cursor off it -- `confirm` selects the
-- cell the cursor is already on, and an arrow with something picked up
-- performs the swap rather than steering -- so the cursor and the pick-up are
-- always the same cell. Two rings there is two outlines describing one thing,
-- which reads as clutter rather than as information. So the ring changes
-- colour instead, and the fruit under it lifts a couple of pixels: one mark,
-- two ways of telling what state it is in. tests/fruits/ui.lua pins the
-- premise, so this stays honest if the input handling ever changes.
local function drawMarkers(gc)
  if board.state ~= "playing" and board.state ~= "paused" then return end

  local h = board.hint
  if h then
    outline(gc, HINT, h.x1, h.y1, 0)
    outline(gc, HINT, h.x2, h.y2, 0)
  end
  outline(gc, sel and SELECT or CURSOR, cur.x, cur.y, 0)
end

-- Drops fields rather than assume the whole line fits: a long game plus a
-- narrow window is exactly when the Nspire would clip it without a word.
local function drawHud(gc)
  col(gc, HUD_BG)
  gc:fillRect(0, 0, ui.w, ui.by)
  col(gc, HUD_RULE)
  gc:drawLine(0, ui.by - 1, ui.w, ui.by - 1)

  gc:setFont("sansserif", "b", 12)
  local titleW = gc:getStringWidth("Fruits")
  local titleFits = titleW + 12 < ui.w
  if titleFits then
    col(gc, GOLD)
    gc:drawString("Fruits", 5, floor((ui.by - 16) / 2), "top")
  end

  -- The side panel already carries the numbers. Repeating them here would
  -- just be two of everything, so the bar keeps the score only when there is
  -- no panel to put it in.
  if ui.panelW > 0 then return end

  gc:setFont("sansserif", "r", 10)
  local stats, statsX
  for _, candidate in ipairs({
    "Score " .. board.score .. "   Best " .. board.best .. "   Moves " .. board.moves,
    "Score " .. board.score .. "   Best " .. board.best,
    "Score " .. board.score,
  }) do
    stats = candidate
    statsX = ui.w - gc:getStringWidth(candidate) - 6
    if not titleFits or statsX > titleW + 12 then break end
  end

  col(gc, TEXT)
  gc:drawString(stats, max(3, statsX), floor((ui.by - 14) / 2), "top")
end

-- One "LABEL      value" row. Measured and right-aligned rather than laid out
-- on an assumed character width, because the font is unknown until runtime and
-- a five-digit score is exactly when a guess would overflow the panel.
local function panelRow(gc, label, value, x, y, w, accent)
  gc:setFont("sansserif", "r", 9)
  col(gc, DIM)
  gc:drawString(label, x, y + 1, "top")
  gc:setFont("sansserif", "b", 11)
  col(gc, accent or TEXT)
  gc:drawString(value, x + max(0, w - gc:getStringWidth(value)), y, "top")
  return y + 17
end

local function drawPanel(gc)
  if ui.panelW <= 0 then return end
  local x, y, w = ui.panelX, ui.by, ui.panelW
  col(gc, PANEL_BG)
  gc:fillRect(x, y, w, ui.panelH)

  local ix, iw = x + 9, w - 18
  local cy = y + 9

  gc:setFont("sansserif", "r", 9)
  col(gc, DIM)
  gc:drawString("SCORE", ix, cy, "top")
  cy = cy + 12
  gc:setFont("sansserif", "b", 24)
  col(gc, GOLD)
  local sc = tostring(board.score)
  -- Step the score down through the sizes rather than let it run off the
  -- panel: six figures at 24pt does not fit and the Nspire would clip it
  -- without a word.
  for _, size in ipairs({ 24, 16, 12 }) do
    gc:setFont("sansserif", "b", size)
    if gc:getStringWidth(sc) <= iw then break end
  end
  gc:drawString(sc, ix + max(0, iw - gc:getStringWidth(sc)), cy, "top")
  cy = cy + 28

  col(gc, HUD_RULE)
  gc:drawLine(ix, cy, ix + iw, cy)
  cy = cy + 7

  cy = panelRow(gc, "BEST", tostring(board.best), ix, cy, iw)
  cy = panelRow(gc, "MOVES", tostring(board.moves), ix, cy, iw)
  cy = panelRow(gc, "CLEARED", tostring(board.cleared), ix, cy, iw)

  -- The chain multiplier only means anything while a cascade is running, so it
  -- shows live then and the round's best otherwise.
  local live = board.chain and board.chain > 1
  cy = panelRow(gc, live and "CHAIN" or "BEST CHAIN",
                "x" .. Fruit.chainMult(live and board.chain or board.bestChain),
                ix, cy, iw, live and HINT or nil)

  if board.lastGain and board.lastGain > 0 and board:busy() then
    gc:setFont("sansserif", "b", 16)
    col(gc, GOLD)
    local t = "+" .. board.lastGain
    gc:drawString(t, ix + max(0, iw - gc:getStringWidth(t)), cy + 6, "top")
  end
end

local function drawHint(gc)
  if not ui.hint then return end
  gc:setFont("sansserif", "r", 9)
  col(gc, DIM)
  for _, text in ipairs({
    "Arrows move   enter picks up   arrow swaps   H hint   R restart",
    "Arrows move   enter picks up   H hint   R restart",
    "enter picks up   H hint   R restart",
    "H hint   R restart",
  }) do
    local w = gc:getStringWidth(text)
    if w <= ui.w - 8 then
      gc:drawString(text, floor((ui.w - w) / 2), ui.hintY, "top")
      return
    end
  end
end

-- lines: array of { text, highlight }. The same overlay shape the other games
-- use, clamped to the window because the computer software can be resized
-- smaller than the panel's natural size and the Nspire clips silently.
local function overlay(gc, title, lines, accent)
  gc:setFont("sansserif", "b", 16)
  local titleW = gc:getStringWidth(title)

  gc:setFont("sansserif", "r", 10)
  local maxW = titleW
  for _, l in ipairs(lines) do
    maxW = max(maxW, gc:getStringWidth(l[1]))
  end

  local pad, lineH = 12, 14
  local bw = min(maxW + pad * 2, ui.w - 4)
  local bh = min(24 + #lines * lineH + pad * 2, ui.h - 4)
  local bx = max(2, floor((ui.w - bw) / 2))
  local by = max(2, floor((ui.h - bh) / 2))

  col(gc, PANEL_BG)
  gc:fillRect(bx, by, bw, bh)
  col(gc, accent)
  gc:drawRect(bx, by, bw, bh)

  gc:setFont("sansserif", "b", 16)
  col(gc, accent)
  gc:drawString(title, bx + floor((bw - titleW) / 2), by + pad - 2, "top")

  gc:setFont("sansserif", "r", 10)
  local y = by + pad + 22
  for _, l in ipairs(lines) do
    col(gc, l[2] and TEXT or DIM)
    gc:drawString(l[1], bx + floor((bw - gc:getStringWidth(l[1])) / 2), y, "top")
    y = y + lineH
  end
end

-- True while a modal panel is up. The side panel is skipped then: the overlay
-- is centred on the window and the panel is not, so the two collide, and the
-- overlay repeats the numbers that matter anyway.
local function overlayUp()
  local s = board.state
  return s == "ready" or s == "paused" or s == "over"
end

local function drawOverlay(gc)
  local s = board.state
  if s == "ready" then
    overlay(gc, "FRUITS", {
      { "Swap two neighbours to line up three" },
      { "Arrows or 2/4/6/8 move   enter picks up" },
      { "With one picked up, an arrow swaps it" },
      { "Chains multiply; no move left ends it" },
      { "Press enter to play", true },
    }, GOLD)
  elseif s == "paused" then
    overlay(gc, "PAUSED", {
      { "Score " .. board.score .. "     Best " .. board.best },
      { "Press enter to resume", true },
    }, GOLD)
  elseif s == "over" then
    overlay(gc, "NO MOVES LEFT", {
      { "Score " .. board.score .. "     Best " .. board.best },
      { board.cleared .. " fruit cleared in " .. board.moves .. " moves" },
      { "Longest chain x" .. Fruit.chainMult(board.bestChain) },
      { "Press enter for a new board", true },
    }, RED)
  end
end

function on.paint(gc)
  col(gc, PAGE_BG)
  gc:fillRect(0, 0, ui.w, ui.h)

  markMoving()
  drawCells(gc)
  drawStatic(gc)
  drawMoving(gc)

  -- After the fruit, deliberately: newcomers fall in from above the board and
  -- these two cover the overflow.
  drawHud(gc)
  if not overlayUp() then drawPanel(gc) end

  drawMarkers(gc)
  drawHint(gc)
  drawOverlay(gc)
end
